/**
 * Main function to process input and generate output.
 * @param {string[]} dataRows - An array of input lines.
 */
function solveProblem(dataRows) {
  // Parse the first line of input to get N (number of vertices) and K (target number of edges).
  const [vertexCount, targetEdgeCount] = _slicedToArray(
    dataRows[0].split(' ').map(Number),
    2
  );

  let candidateM = vertexCount; // Initialize M, representing a specific vertex count for a sub-structure.
  let solutionFound = false; // Flag to indicate if a valid M is found.

  // Iterate downwards from N to 1 to find a suitable M.
  // This loop searches for a specific graph structure.
  for (; candidateM >= 0x1; candidateM--) {
    const remainingVertices = vertexCount - candidateM + 0b1; // Calculate L based on N and current M.

    // Check if the current M satisfies the condition for K.
    // The formula represents the number of edges in a specific graph construction.
    if (((remainingVertices - 0b1) * (remainingVertices - 2.0)) / 2.0 + candidateM - 0b1 === targetEdgeCount) {
      solutionFound = true; // A valid M has been found.
      break; // Exit the loop as we found the largest suitable M.
    }
  }

  // If no valid M was found after checking all possibilities, output -1.
  if (!solutionFound) {
    console.log(-0x1);
    return;
  }

  // Output the found M and the total number of edges.
  console.log(`M=${candidateM}`);
  console.log(vertexCount - 0b1); // Total edges in the constructed graph.

  // Print edges for the first part of the graph (a path).
  // This forms a path from vertex 1 to M+1.
  for (let currentIdx = 0b1; currentIdx <= candidateM; currentIdx++) {
    console.log(`${currentIdx} ${currentIdx + 0b1}`);
  }

  // Print edges for the second part of the graph (star-like structure).
  // Connects vertex M+1 to all remaining vertices from M+2 to N.
  for (let anotherIdx = candidateM + 2.0; anotherIdx <= vertexCount; anotherIdx++) {
    console.log(`${candidateM + 0b1} ${anotherIdx}`);
  }
}

/**
 * Sets up standard input processing and calls the main solver function.
 */
function executeWithStandardInput() {
  let accumulatedInput = ""; // Buffer to store incoming data.
  process.stdin.resume(); // Ensure stdin is open.
  process.stdin.setEncoding("utf8"); // Set encoding for input.

  // Event listener for data chunks.
  process.stdin.on("data", function (dataSegment) {
    accumulatedInput += dataSegment; // Append data to buffer.
  });

  // Event listener for end of input.
  process.stdin.on("end", function () {
    solveProblem(accumulatedInput.split("\n")); // Split input by newlines and pass to solver.
  });
}

// Initiate the process of reading from standard input.
executeWithStandardInput();
